"""Mechanically derive a healthy-only execution path; preserve frozen v41 files."""
from pathlib import Path
root=Path('reports/model-evolution-20261016')
def once(s,old,new):
    assert s.count(old)==1,(old,s.count(old))
    return s.replace(old,new)
s=Path('reports/player-impact-v41/probe-worker.mjs').read_text(encoding='utf-8')
s=once(s,"from './ovr-input.mjs'","from '../player-impact-v41/ovr-input.mjs'")
s=once(s,"from './engine.mjs'","from '../player-impact-v41/engine.mjs'")
s=once(s,"const arms=[['fullCapCounterfactual',cap],['supportedHealthy',e.supportedMinutes]];","const arms=[['supportedHealthy',e.supportedMinutes]];")
(root/'healthy-ovr-worker.mjs').write_text(s,encoding='utf-8')
s=(root/'latest-full-ovr.mjs').read_text(encoding='utf-8')
s=once(s,"const original=read('reports/player-impact-v41/probe-protocol.json');","const original=read('reports/player-impact-v41/probe-protocol.json');\nconst parity=read('reports/model-evolution-20261016/healthy-parity.json');if(!parity.passed)throw Error('Parity check missing');\nif(sha('reports/model-evolution-20261016/healthy-ovr-worker.mjs')!==parity.workerSHA256)throw Error('Verified worker drift');\nconst oldCheckpointSHA256=sha(root+'/checkpoint.jsonl');\nconst importedRows=fs.readFileSync(root+'/checkpoint.jsonl','utf8').trim().split('\\n').filter(Boolean).map(JSON.parse);\nconst workersCount=6;")
s=once(s,"const hashes={...original.hashes,'reports/model-evolution-20261016/latest-full-ovr.mjs':sha('reports/model-evolution-20261016/latest-full-ovr.mjs')};","const hashes={...original.hashes,...Object.fromEntries(['reports/model-evolution-20261016/healthy-full-ovr.mjs','reports/model-evolution-20261016/healthy-ovr-worker.mjs','reports/model-evolution-20261016/healthy-parity.json','reports/model-evolution-20261016/latest-full-ovr.mjs',root+'/checkpoint.jsonl',root+'/protocol.json'].map(f=>[f,sha(f)]))};")
s=once(s,"ids:x.players.map(p=>p.playerId).sort((a,b)=>a-b),hashes,","ids:x.players.map(p=>p.playerId).sort((a,b)=>a-b),hashes,executionMode:'healthy-only',workers:workersCount,importedPlayers:importedRows.length,oldCheckpointSHA256,")
s=once(s,"frozen v41 healthy-load and full-cap paired protocols","frozen v41 healthy-load paired protocol; full-cap diagnostic omitted for remaining players")
s=once(s,"FullCap is a separate diagnostic.","FullCap is available only for preserved earlier rows; it never affects the ranking.")
s=once(s,"const fingerprint=sha('reports/model-evolution-20261016/latest-full-ovr.mjs')","const fingerprint=sha('reports/model-evolution-20261016/healthy-full-ovr.mjs')")
s=once(s,"const pf=root+'/protocol.json',cf=root+'/checkpoint.jsonl';","const pf=root+'/healthy-protocol.json',cf=root+'/healthy-checkpoint.jsonl';")
s=once(s,"fullCap:summarizeArm(m.result.arms.find(a=>a.arm==='fullCapCounterfactual'))","fullCap:null")
s=once(s,"if(!rows.length){\n const previous=read('reports/player-impact-v41/probe-checkpoint.json');\n for(const m of previous.rows.filter(r=>r.job.variant==='v41')){const row=summarize(m,true);rows.push(row);fs.appendFileSync(cf,JSON.stringify(row)+'\\n');}\n}","if(!rows.length){for(const row of importedRows){rows.push(row);fs.appendFileSync(cf,JSON.stringify(row)+'\\n');}}")
s=once(s,"playersCompleted:rows.length,totalPlayers:protocol.ids.length,reused:","playersCompleted:rows.length,totalPlayers:protocol.ids.length,workers:workersCount,executionMode:'healthy-only',preservedPlayers:importedRows.length,reused:")
s=once(s,"remaining:jobs.length,workers:4","remaining:jobs.length,workers:workersCount")
s=once(s,"Math.min(4,jobs.length)","Math.min(workersCount,jobs.length)")
s=once(s,"new URL('../player-impact-v41/probe-worker.mjs',import.meta.url)","new URL('./healthy-ovr-worker.mjs',import.meta.url)")
s=once(s,"allFrozenSourceHashesPassed:true,checkpointSHA256:","allFrozenSourceHashesPassed:true,healthyOnlyParityPassed:true,preservedPlayers:importedRows.length,checkpointSHA256:")
(root/'healthy-full-ovr.mjs').write_text(s,encoding='utf-8')
print('Prepared healthy-only worker and 6-worker resumable runner. Frozen files unchanged.')
